import json,subprocess
from datetime import datetime,timezone
from pathlib import Path
from .runtime import ROOT,Run,sha,state,publish,checkpoint,atomic,utc,preserve_check
from .baselines import strong_specs
from .datasets import SLMAN,SL

def main():
    st=state();assert st['stages']['G3'] in ['passed','scientifically_negative'];assert not st['new_independent_test_opened']
    run=Run('g4_freeze','seen-only empirical freeze after bounded public-source audit',dict(independent_data_status='INDEPENDENT_TEST_UNAVAILABLE',selection_uses_no_new_performance=True));print(run.id,flush=True)
    run.command([str(ROOT/'.venv-v2-smr/bin/python'),'-m','pytest','tests','experiments/temporal_vpr/tests','experiments/endpoint_vpr/tests','experiments/paper_v2/test_manuscript_audit.py','-q','--junitxml='+str(run.path/'all_tests.xml')],env={'PYTHONPATH':'','PYTEST_DISABLE_PLUGIN_AUTOLOAD':'1'})
    # Stop camera download at login, not bypass it. Public SFU actual failures are retained.
    selection=json.loads((ROOT/'configs/v3/dataset_selection.json').read_text());assert len(selection['heads'])==6 and not any(r.get('status') in [200,206] for r in selection['heads']);assert (ROOT/'docs/research_v3/NEW_DATASET_PREFLIGHT.md').exists()
    chosen=json.loads((ROOT/'configs/v3/v3_selected_methods.json').read_text());specs=strong_specs()+list(chosen['selected'].values());p=chosen['selected']['P'];specs += [dict(p,name='P_epsilon_zero',epsilon=0),dict(name='R1_same_P_pool',kind='R1',backend=p['backend'],H=p['H'],r=p['r']),dict(name='R3_same_P_radius',kind='R1',backend=p['backend'],H=1,r=p['r'])]
    manifest=json.loads(SLMAN.read_text());manifest['V3_role']='seen/development_only';manifest['original_V2_role_fields_preserved_as_provenance']=True
    for r in manifest['records']:r['V3_role']='gallery' if r['role']=='gallery' else 'seen_query'
    folder=ROOT/'freezes'/('v3_'+datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ'));folder.mkdir(parents=True,exist_ok=False)
    atomic(folder/'manifest.json',manifest);ident=json.loads((SL/'score_identities.json').read_text());atomic(folder/'model_identity.json',{m:v['fingerprint'] for m,v in ident.items()})
    (folder/'HYPOTHESES_AND_RISKS.md').write_text('Frozen before any new independent prediction. All evaluated images below are already seen St Lucia, not new testing. Hypothesis: P reduces drift while preserving temporal support; development gate result must remain intact. Independent geographic/recognition generalization cannot be verified because Oxford needs registration and SFU official archives failed normal public access. No more modules, parameters, tolerances or datasets selected using performance. Timing is actual image processing, warm20, batch1, three complete passes per frozen method. No significance from correlated frames/repeats; no deployment claim.\n')
    files=[p for p in (ROOT/'experiments/endpoint_vpr').rglob('*') if p.suffix in ['.py','.tex','.txt']]+list((ROOT/'configs/v3').glob('*'))+[ROOT/'src/vpr_research/encoders/frozen.py',SLMAN,SL/'score_identities.json']
    scientific={str(p.relative_to(ROOT)):sha(p) for p in files if p.is_file()};preserve_check()
    freeze=dict(goal_id='VPR-GOAL-V3',freeze_timestamp_utc=utc(),source_git_commit=subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip(),science_file_sha256=scientific,methods=specs,selection=chosen,seen_data=['Nordland','St_Lucia','Gardens_Point'],independent_dataset=None,independent_data_status='INDEPENDENT_TEST_UNAVAILABLE',independent_performance_not_opened=True,manifest_sha256=sha(folder/'manifest.json'),model_identity_sha256=sha(folder/'model_identity.json'),primary='St_Lucia_seen_10m',auxiliary='25m',sensitivity=[5,15,50],startup=8,common_mask='radius-specific_no-positive_exclusion_shared_all_methods_then_first8_exclusion',timing=dict(warm=20,full_passes=3,batch_size=1,device='cuda',CUDA_synchronized=True,includes=['decode','preprocess','encoding','CPU_transfer','similarity','history','complete_ranking'],clock_locked=False),descriptor_atol=2e-5,score_atol=2e-5,novelty_claim_supported=False)
    atomic(folder/'freeze.json',freeze);atomic(ROOT/'configs/v3/v3_frozen_protocol.yaml',freeze);run.write('freeze.json',freeze);run.write('model_identity.json',{m:v['fingerprint'] for m,v in ident.items()});run.write('manifest.json',manifest);run.finish(dict(freeze_directory=str(folder.relative_to(ROOT)),methods=len(specs),new_raw_image_download_bytes=0,independent_status='INDEPENDENT_TEST_UNAVAILABLE'),dict(passed=True,old_preserved=True,new_independent_performance_not_opened=True,independent_dataset_gate=False,empirical_seen_only_route_per_section4_4=True))
    report=f'''# G4 acceptance\n1. Added immutable freeze {folder.name}: methods, code/model/data hashes, seen manifest, protocol, UTC and prospective risks.\n2. Source selection is metadata-only: Oxford RTK is promising but public camera entry requires registration; no account/terms action. SFU has explicit CC BY 4.0 and manual places, but all three official necessary archives failed HTTP HEAD and bounded GET; HTTPS fails TLS, direct normal GET also times out. Downloader/VPR-Bench alternatives lack confirmed task-compatible licensed new subset in this bounded audit.\n3. `.venv-p0/bin/python -m experiments.endpoint_vpr.run_g4`; actual access attempts in two earlier metadata runs and command events. No new image encoded or scored.\n4. Status INDEPENDENT_TEST_UNAVAILABLE; new raw image bytes=0. Frozen {len(specs)} methods can be audited on seen data and timed genuinely.\n5. St Lucia remains seen; neither its new split nor its V3 freeze grants independence. No metric-precision result inferred from SFU approximate manual spacing/GPS.\n6. Continue the explicitly allowed empirical/limitations route (§4.4). Independent performance gate fails honestly; no new method contribution asserted.\n7. External generalization is unresolved; registration/authorized data would require a new source audit and pretest freeze before any new scores.\n8. All freeze/code/images identity hashes and original-source failures retained; next checkpoint backs up freeze before timing.\n9. Next: actual real-image three-pass timing and fixed-protocol seen-data numeric audit; independent testing explicitly not run.\n'''
    publish('g4',run,report);(ROOT/'docs/research_v3/DATA_PROTOCOL.md').open('a').write('\nG4 independent_status=INDEPENDENT_TEST_UNAVAILABLE. Freeze '+folder.name+' is seen-only, not a substitute external test. SFU manual matches are place identity, never 10m metric GT.\n');st['stages']['G4']='passed_seen_only_independent_unavailable';state(stages=st['stages'],current_stage='G5',g4_run=run.id,freeze_directory=str(folder.relative_to(ROOT)),latest_run_id=run.id,independent_status='INDEPENDENT_TEST_UNAVAILABLE');checkpoint('G4')
if __name__=='__main__':main()
